    std.debug.assert(@offsetOf(ReadOptions, "rate") == 0);
    std.debug.assert(@offsetOf(ReadOptions, "name_column") == 8);
    std.debug.assert(@offsetOf(ReadOptions, "ignore_timecode_mismatch") == if (pointers == 4) 12 else 16);
}

comptime {
    std.debug.assert(@sizeOf(TimeRange) == 32);
    std.debug.assert(@alignOf(TimeRange) == 8);
    std.debug.assert(@offsetOf(TimeRange, "start_time") == 0);
    std.debug.assert(@offsetOf(TimeRange, "duration") == 16);
}

comptime {
